// HR Policy Q&A Bot: core logic (ported from main.py)
const HANDBOOK = "# Staff Handbook (sample)\n\n## Annual leave\nFull-time staff receive 20 working days of annual leave per year. Leave accrues monthly and up to 5 unused days can be carried into the next year. Requests must be submitted at least two weeks in advance through your line manager.\n\n## Sick leave\nStaff are entitled to 10 paid sick days per year. A medical certificate is required for absences longer than two consecutive days.\n\n## Remote work\nStaff may work remotely up to two days per week with their manager's approval. Fridays are remote-friendly by default unless a client meeting is scheduled. Core hours are 10am to 3pm.\n\n## Overtime\nOvertime must be approved in advance by your head of department. Approved overtime is paid at 1.5 times the hourly rate or taken as time off in lieu within one month.\n\n## Travel and transport\nTransport for client visits within Lagos is reimbursed up to NGN 15,000 per day with receipts. Inter-state travel requires a travel request approved by the operations manager, and hotel stays are capped at NGN 60,000 per night.\n\n## Code of conduct\nStaff must treat colleagues and clients with respect. Harassment of any kind is not tolerated and should be reported to HR or the confidential whistleblowing line.\n";
// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const STOP = new Set('a an the of to and or in on for is are do does i my me we our can how what when who with be at by it this that if as from you your get much many'.split(' '));
const tok = s => (s.toLowerCase().match(/[a-z0-9]+/g) || []).filter(t => !STOP.has(t)).map(t => t.endsWith('s') && t.length > 3 ? t.slice(0, -1) : t);
const secs = HANDBOOK.split(/^##\s+/m).slice(1).map(p => { const [title, ...rest] = p.split('\n'); return { title: title.trim(), text: rest.join(' ').trim() }; });
const tfs = secs.map(s => tok(s.title + ' ' + s.text).reduce((m, t) => (m[t] = (m[t] || 0) + 1, m), {}));
const df = {}; tfs.forEach(tf => Object.keys(tf).forEach(t => df[t] = (df[t] || 0) + 1));
const idf = t => Math.log((secs.length + 1) / ((df[t] || 0) + 1)) + 1;
const vec = tf => { const v = {}; let n = 0; for (const [t, c] of Object.entries(tf)) { v[t] = c * idf(t); n += v[t] ** 2; } n = Math.sqrt(n) || 1; for (const t in v) v[t] /= n; return v; };
const vs = tfs.map(vec);
return input.map(({ question }) => {
  const qv = vec(tok(question).reduce((m, t) => (m[t] = (m[t] || 0) + 1, m), {}));
  const scores = vs.map(v => Object.keys(qv).reduce((s, t) => s + qv[t] * (v[t] || 0), 0));
  const i = scores.indexOf(Math.max(...scores)), conf = Math.round(scores[i] * 100) / 100;
  if (conf < 0.25) return { json: { route: 'ask HR', question, answer: "I'm not sure the handbook covers that. I've passed your question to HR.", source: null, confidence: conf } };
  const qt = new Set(tok(question));
  const best = secs[i].text.split(/(?<=[.!?])\s+/).sort((a, b) => tok(b).filter(t => qt.has(t)).length - tok(a).filter(t => qt.has(t)).length).slice(0, 2).join(' ');
  return { json: { route: 'answered', question, answer: best, source: secs[i].title, confidence: conf } };
});
